  testWidgets(
    'every physics (PHY121/122/124) field renders without a hard failure',
    (WidgetTester tester) async {
      final List<String> broken = <String>[];
      for (final String field in fields) {
        await tester.pumpWidget(
          MaterialApp(home: Scaffold(body: MathText(field))),
        );
        await tester.pumpAndSettle();
        final Object? err = tester.takeException();
        final bool hasMath = MathText.hasMath(field);
        final bool mathWidgetExists = !hasMath || find.byType(Math).evaluate().isNotEmpty;
        if (err != null) {
          // A Math widget existing in the tree despite an exception means
          // the formula parsed and built fine -- the exception is a
          // downstream debug-only layout assertion from this test's bare,
          // unconstrained-width harness (unlike the real app's cards/lists),
          // not a parsing failure. A release build never throws on layout
          // overflow, so that case is a soft pass here.
          if (!mathWidgetExists) {
            broken.add('EXCEPTION (\$err): \$field');
          }
          continue;
        }
        if (!mathWidgetExists) {
          broken.add('FALLBACK (no Math widget rendered): \$field');
        }
      }
      expect(broken, isEmpty, reason: broken.join('X'));
    },
  );
}
